"""Generate the P8b multi-window platd fixture DTB.

The tree is our own construction: one platform node with three page-sized `reg`
windows so devd can create and transfer the mailbox/GPIO/RNG handles in order.
Run from the repository root:

    python3 tests/fixtures/pi4-platd/generate.py
"""

from __future__ import annotations

import struct
from pathlib import Path

FDT_MAGIC = 0xD00D_FEED
FDT_BEGIN_NODE = 1
FDT_END_NODE = 2
FDT_PROP = 3
FDT_END = 9
HEADER_BYTES = 40
RSVMAP_BYTES = 16

OUT = Path(__file__).resolve().parent


class Node:
    def __init__(self, name: str, props=None, children=None):
        self.name = name
        self.props = props or []
        self.children = children or []


def be32(values) -> bytes:
    return b"".join(struct.pack(">I", value & 0xFFFF_FFFF) for value in values)


def text(value: str) -> bytes:
    return value.encode() + b"\0"


def text_list(values) -> bytes:
    return b"".join(text(value) for value in values)


def pad4(block: bytearray) -> None:
    while len(block) % 4:
        block.append(0)


def encode_node(node: Node, strings: dict[str, int], string_blob: bytearray,
                structure: bytearray) -> None:
    structure += struct.pack(">I", FDT_BEGIN_NODE)
    structure += node.name.encode() + b"\0"
    pad4(structure)
    for name, value in node.props:
        if name not in strings:
            strings[name] = len(string_blob)
            string_blob += name.encode() + b"\0"
        structure += struct.pack(">III", FDT_PROP, len(value), strings[name])
        structure += value
        pad4(structure)
    for child in node.children:
        encode_node(child, strings, string_blob, structure)
    structure += struct.pack(">I", FDT_END_NODE)


def encode_tree(root: Node) -> bytes:
    strings: dict[str, int] = {}
    string_blob = bytearray()
    structure = bytearray()
    encode_node(root, strings, string_blob, structure)
    structure += struct.pack(">I", FDT_END)

    struct_offset = HEADER_BYTES + RSVMAP_BYTES
    strings_offset = struct_offset + len(structure)
    total = strings_offset + len(string_blob)
    header = struct.pack(
        ">10I",
        FDT_MAGIC,
        total,
        struct_offset,
        strings_offset,
        HEADER_BYTES,
        17,
        16,
        0,
        len(string_blob),
        len(structure),
    )
    return header + bytes(RSVMAP_BYTES) + bytes(structure) + bytes(string_blob)


def tree() -> Node:
    return Node(
        "",
        [
            ("compatible", text_list(["raven,pi4-platd-fixture"])),
            ("model", text("RavenBSD Pi 4 platd fixture")),
            ("#address-cells", be32([2])),
            ("#size-cells", be32([2])),
        ],
        [
            Node(
                "platd@fd580000",
                [
                    ("compatible", text_list(["raven,pi4-platform"])),
                    (
                        "reg",
                        be32(
                            [
                                0x0,
                                0xFD58_0000,
                                0x0,
                                0x1000,
                                0x0,
                                0xFD58_1000,
                                0x0,
                                0x1000,
                                0x0,
                                0xFD58_2000,
                                0x0,
                                0x1000,
                            ]
                        ),
                    ),
                    ("status", text("okay")),
                ],
            )
        ],
    )


def dts() -> str:
    return """// SPDX-License-Identifier: BSD-3-Clause
// Copyright (c) 2026, Bo Maryniuk and RavenBSD contributors
// Generated by tests/fixtures/pi4-platd/generate.py.
/dts-v1/;

/ {
    compatible = "raven,pi4-platd-fixture";
    model = "RavenBSD Pi 4 platd fixture";
    #address-cells = <0x2>;
    #size-cells = <0x2>;
    platd@fd580000 {
        compatible = "raven,pi4-platform";
        reg = <0x0 0xfd580000 0x0 0x1000>,
              <0x0 0xfd581000 0x0 0x1000>,
              <0x0 0xfd582000 0x0 0x1000>;
        status = "okay";
    };
};
"""


def hex_fixture(data: bytes) -> str:
    lines = [
        "# SPDX-License-Identifier: BSD-3-Clause",
        "# Copyright (c) 2026, Bo Maryniuk and RavenBSD contributors",
        "# Hexadecimal bytes of the generated DTB; build.sh decodes this file.",
    ]
    for offset in range(0, len(data), 32):
        lines.append(data[offset:offset + 32].hex())
    return "\n".join(lines) + "\n"


def main() -> None:
    (OUT / "pi4-platd.dtb.hex").write_text(hex_fixture(encode_tree(tree())))
    (OUT / "pi4-platd.dts").write_text(dts())


if __name__ == "__main__":
    main()
